<?php /* login.php */ ?>
<?php
require_once __DIR__ . '/auth.php';
$u = usuarioLogado();
if ($u) {
    header('Location: ' . ($u['tipo']==='superadmin' ? 'superadmin.php' : ($u['tipo']==='admin' ? 'admin.php' : 'cliente.php')));
    exit;
}
$erro = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (login($_POST['email']??'', $_POST['senha']??'')) {
        $u = usuarioLogado();
        header('Location: ' . ($u['tipo']==='superadmin' ? 'superadmin.php' : ($u['tipo']==='admin' ? 'admin.php' : 'cliente.php')));
        exit;
    }
    // Verifica se é erro de e-mail não confirmado
    if (isset($_SESSION['login_erro']) && $_SESSION['login_erro'] === 'email_nao_confirmado') {
        $erro = '⚠️ Confirme seu e-mail antes de entrar. Verifique sua caixa de entrada.';
        unset($_SESSION['login_erro']);
    } else {
        $erro = 'E-mail ou senha incorretos.';
    }
}
if (($_GET['erro']??'') === 'acesso') $erro = 'Acesso não autorizado.';
?>
