<script>document.addEventListener("DOMContentLoaded",()=>{const upd=()=>{const ic=document.getElementById("themeIcon");if(ic)ic.textContent=OpaTheme.get()==="light"?"☀️":"🌙";};upd();const tg=document.getElementById("themeToggle");if(tg){tg.checked=OpaTheme.get()==="light";tg.addEventListener("change",()=>setTimeout(upd,50));}})</script>
<script>
(function(){
  const DARK  = "data:image/png;base64,";
  const LIGHT = "data:image/png;base64,";
  function syncLogos(){
    // Usa tema do sistema OU o definido pelo toggle
    const isLight = (document.documentElement.getAttribute('data-tema') || 
                     (window.matchMedia('(prefers-color-scheme:light)').matches ? 'light' : 'dark')) === 'light';
    const src = isLight ? LIGHT : DARK;
    ['navLogo','logoMain','logoReg','heroLogo','logoFb'].forEach(id=>{
      const el = document.getElementById(id);
      if(el && el.tagName==='IMG') el.src = src;
    });
  }
  // Observa mudanças no atributo data-tema (toggle do usuário)
  new MutationObserver(syncLogos).observe(document.documentElement, {attributes:true, attributeFilter:['data-tema']});
  window.matchMedia('(prefers-color-scheme:light)').addEventListener('change', syncLogos);
  document.addEventListener('DOMContentLoaded', syncLogos);
  syncLogos();
})();
</script>
